	_ = params
	var marketsPromise any = this.PublicMarketPostFullV1AllInstruments(params)
	//
	//    {
	//        "result": [
	//            {
	//                "instrument": "AAVE_USDT_Perp",
	//                "instrument_hash": "0x032201",
	//                "base": "AAVE",
	//                "quote": "USDT",
	//                "kind": "PERPETUAL",
