func (this *GrvtCore) ParseMarket(market any) any {
	//
	//    {
	//        "instrument": "BTC_USDT_Perp",
	//        "instrument_hash": "0x030501",
	//        "base": "BTC",
	//        "quote": "USDT",
	//        "kind": "PERPETUAL",
	//        "venues": [
	//            "ORDERBOOK",
	//            "RFQ"
	//        ],
	//        "settlement_period": "PERPETUAL",
	//        "base_decimals": 9,
	//        "quote_decimals": 6,
	//        "tick_size": "0.1",
	//        "min_size": "0.001",
	//        "create_time": "1768040726362828205",
	//        "max_position_size": "1000.0",
	//        "funding_interval_hours": 8,
	//        "adjusted_funding_rate_cap": "0.3",
	//        "adjusted_funding_rate_floor": "-0.3",
	//        "min_notional": "100.0"
	//    }
	//
	var marketId *string = this.SafeString(market, "instrument")
	var baseId *string = this.SafeString(market, "base")
	var quoteId *string = this.SafeString(market, "quote")
	var settleId any = quoteId
	var base any = this.SafeCurrencyCode(baseId)
	var quote any = this.SafeCurrencyCode(quoteId)
	var settle any = this.SafeCurrencyCode(settleId)
	var symbol any = Add(Add(Add(Add(base, "/"), quote), ":"), settle)
	var typeVar any = nil
	var typeRaw *string = this.SafeString(market, "kind")
	if typeRaw != nil && *typeRaw == "PERPETUAL" {
		typeVar = "swap"
	}
	var isSpot bool = (IsEqual(typeVar, "spot"))
	var isSwap bool = (IsEqual(typeVar, "swap"))
	var isFuture bool = (IsEqual(typeVar, "future"))
	var isContract bool = isSwap || isFuture
	return map[string]any{
		"id":             marketId,
		"symbol":         symbol,
		"base":           base,
		"quote":          quote,
		"settle":         settle,
		"baseId":         baseId,
		"quoteId":        quoteId,
		"settleId":       settleId,
		"type":           typeVar,
		"spot":           isSpot,
		"margin":         false,
		"swap":           isSwap,
		"future":         isFuture,
		"option":         false,
		"active":         nil,
		"contract":       isContract,
		"linear":         Ternary(isSwap, true, nil),
		"inverse":        Ternary(isSwap, false, nil),
		"contractSize":   this.ParseNumber("1"),
		"expiry":         nil,
		"expiryDatetime": nil,
		"strike":         nil,
		"optionType":     nil,
		"precision": map[string]any{
			"amount": this.SafeNumber(market, "min_size"),
			"price":  this.SafeNumber(market, "tick_size"),
			"base":   this.ParseNumber(this.ParsePrecision(this.SafeString(market, "base_decimals"))),
			"quote":  this.ParseNumber(this.ParsePrecision(this.SafeString(market, "quote_decimals"))),
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": nil,
			},
			"amount": map[string]any{
				"min": this.SafeNumber(market, "min_size"),
				"max": this.SafeNumber(market, "max_position_size"),
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": this.SafeNumber(market, "min_notional"),
				"max": nil,
			},
		},
		"created": this.SafeIntegerProduct(market, "create_time", 0.000001),
		"info":    market,
	}
}

