func (this *GrvtCore) ParseTrade(trade any, optionalArgs ...any) any {
	//
	// fetchTrades
	//
	//            {
	//                "event_time": "1764779531332118705",
	//                "instrument": "ETH_USDT_Perp",
	//                "size": "23.73",
	//                "price": "3089.88",
	//                "is_rpi": false,
	//                "mark_price": "3089.360002315",
	//                "index_price": "3090.443723246",
	//                "interest_rate": "0.0",
	//                "forward_price": "0.0",
	//                "trade_id": "64796657-1",
	//                "venue": "ORDERBOOK",
	//                "is_taker_buyer": false
	//            }
	//
	// fetchMyTrades
	//
	//            {
	//                "event_time": "1764945709702747558",
	//                "instrument": "BTC_USDT_Perp",
	//                "size": "0.001",
	//                "price": "90000.0",
	//                "is_rpi": false
	//                "mark_price": "90050.164063298",
	//                "index_price": "90089.803654938",
	//                "interest_rate": "0.0",
	//                "forward_price": "0.0",
	//                "trade_id": "65424692-2",
	//                "venue": "ORDERBOOK",
	//                "is_buyer": true,
	//                "is_taker": false,
	//                "broker": "UNSPECIFIED",
	//                "realized_pnl": "0.0",
	//                "fee": "-0.00009",
	//                "fee_rate": "0.0",
	//                "order_id": "0x01010105034cddc7000000006621285c",
	//                "client_order_id": "1375879248",
	//                "signer": "0x42c9f56f2c9da534f64b8806d64813b29c62a01d",
	//                "sub_account_id": "2147050003876484",
	//            }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	var marketId *string = this.SafeString(trade, "instrument")
	market = this.SafeMarket(marketId, market)
	var timestamp *int64 = this.SafeIntegerProduct(trade, "event_time", 0.000001)
	var takerOrMaker any = nil
	var isTakerBuyer any = this.SafeBool(trade, "is_taker_buyer")
	var side any = nil
	if !IsEqual(isTakerBuyer, nil) {
		side = Ternary(EvalTruthy(isTakerBuyer), "buy", "sell")
		takerOrMaker = "taker"
	} else {
		var isTaker bool = (IsEqual(this.SafeBool(trade, "is_taker"), true))
		var isBuyer bool = (IsEqual(this.SafeBool(trade, "is_buyer"), true))
		takerOrMaker = Ternary(isTaker, "taker", "maker")
		side = Ternary(isBuyer, "buy", "sell")
	}
	var fee any = nil
	var feeString *string = this.SafeString(trade, "fee")
	if feeString != nil {
		fee = map[string]any{
			"cost":     this.ParseNumber(feeString),
			"currency": GetValue(market, "quote"),
			"rate":     this.SafeNumber(trade, "fee_rate"),
		}
	}
	return this.SafeTrade(map[string]any{
		"info":         trade,
		"id":           this.SafeString(trade, "trade_id"),
		"timestamp":    timestamp,
		"datetime":     this.Iso8601(timestamp),
		"symbol":       GetValue(market, "symbol"),
		"side":         side,
		"takerOrMaker": takerOrMaker,
		"price":        this.SafeString(trade, "price"),
		"amount":       this.SafeString(trade, "size"),
		"cost":         nil,
		"fee":          fee,
		"order":        this.SafeString(trade, "order_id"),
	}, market)
}

/**
 * @method
 * @name grvt#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://api-docs.grvt.io/market_data_api/#candlestick_1
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest item to fetch
 * @param {int} [limit] the maximum amount of items to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms for the ending date filter, default is the current time
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [availble parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *GrvtCore) FetchOHLCV(symbol any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *GrvtCore) fetchOHLCVBody(ch chan any, symbol any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	timeframe := GetArg(optionalArgs, 0, "1m")
	_ = timeframe
	since := GetArg(optionalArgs, 1, nil)
	_ = since
	limit := GetArg(optionalArgs, 2, nil)
	_ = limit
	params := GetArg(optionalArgs, 3, map[string]any{})
	_ = params
	var maxLimit any = 1000
	if IsEqual(this.Markets, nil) {

		retRes114212 := (<-this.LoadMarkets())
		PanicOnError(retRes114212)
	}
	var paginate any = false
	paginateparamsVariable := this.HandleOptionAndParams(params, "fetchOHLCV", "paginate", false)
	paginate = GetValue(paginateparamsVariable, 0)
	params = GetValue(paginateparamsVariable, 1)
	if EvalTruthy(paginate) {

		retRes114719 := (<-this.FetchPaginatedCallDeterministic("fetchOHLCV", symbol, since, limit, timeframe, params, maxLimit))
		PanicOnError(retRes114719)
		ch <- retRes114719
		return nil
	}
	var market any = this.Market(symbol)
	var request any = map[string]any{
		"instrument": GetValue(market, "id"),
		"interval":   this.SafeString(this.Timeframes, timeframe, timeframe),
	}
	var priceTypeMap map[string]any = map[string]any{
		"last":  "TRADE",
		"mark":  "MARK",
		"index": "INDEX",
	}
	var selectedPriceType *string = this.SafeString(params, "priceType", "last")
	AddElementToObject(request, "type", this.SafeString(priceTypeMap, selectedPriceType))
	if !IsEqual(limit, nil) {
		AddElementToObject(request, "limit", mathMin(limit, 1000))
	}
	requestparamsVariable := this.HandleUntilOptionString("end_time", request, params, 1000000)
	request = GetValue(requestparamsVariable, 0)
	params = GetValue(requestparamsVariable, 1)
	if !IsEqual(since, nil) {
		AddElementToObject(request, "start_time", this.NumberToString(Multiply(since, 1000000)))
	}

	response := (<-this.PublicMarketPostFullV1Kline(this.Extend(request, params)))
	PanicOnError(response)
	//
	//    {
	//        "result": [
	//            {
	//                "open_time": "1767288240000000000",
	//                "close_time": "1767288300000000000",
	//                "open": "88178.8",
	//                "close": "88176.7",
	//                "high": "88192.7",
	//                "low": "88176.6",
	//                "volume_b": "15.32",
	//                "volume_q": "1350962.4782",
	//                "trades": 38,
	//                "instrument": "BTC_USDT_Perp"
	//            },
	//        ],
	//        "next": "eyJvcGVuVGltZSI6MTc2NzI1ODMwMDAwMDAwMDAwMH0"
	//    }
	//
	var candles any = this.SafeList(response, "result", []any{})

	ch <- this.ParseOHLCVs(candles, market, timeframe, since, limit)
	return nil
}
func (this *GrvtCore) ParseOHLCV(ohlcv any, optionalArgs ...any) any {
	//
	//            {
	//                "open_time": "1767288240000000000",
	//                "close_time": "1767288300000000000",
	//                "open": "88178.8",
	//                "close": "88176.7",
	//                "high": "88192.7",
	//                "low": "88176.6",
	//                "volume_b": "15.32",
	//                "volume_q": "1350962.4782",
	//                "trades": 38,
	//                "instrument": "BTC_USDT_Perp"
	//            }
	//
	market := GetArg(optionalArgs, 0, nil)
	_ = market
	return []any{this.SafeIntegerProduct(ohlcv, "open_time", 0.000001), this.SafeNumber(ohlcv, "open"), this.SafeNumber(ohlcv, "high"), this.SafeNumber(ohlcv, "low"), this.SafeNumber(ohlcv, "close"), this.SafeNumber(ohlcv, "volume_b")}
}

