func (this *GrvtCore) fetchBalanceBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	params := GetArg(optionalArgs, 0, map[string]any{})
	_ = params

	retRes13188 := (<-this.LoadMarketsAndSignIn())
	PanicOnError(retRes13188)
	var request map[string]any = map[string]any{
		"sub_account_id": this.GetSubAccountId(params),
	}

	response := (<-this.PrivateTradingPostFullV1AccountSummary(this.Extend(request, params)))
	PanicOnError(response)
	//
	//    {
	//        "result": {
	//            "event_time": "1764863116142428457",
	//            "sub_account_id": "2147050003876484",
	//            "margin_type": "SIMPLE_CROSS_MARGIN",
	//            "settle_currency": "USDT",
	//            "unrealized_pnl": "0.0",
	//            "total_equity": "15.0",
	//            "initial_margin": "0.0",
	//            "maintenance_margin": "0.0",
	//            "available_balance": "15.0",
	//            "spot_balances": [
	//                {
	//                    "currency": "USDT",
	//                    "balance": "15.0",
	//                    "index_price": "1.000289735"
	//                }
	//            ],
	//            "positions": [],
	//            "settle_index_price": "1.000289735",
	//            "derisk_margin": "0.0",
	//            "derisk_to_maintenance_margin_ratio": "1.0",
	//            "total_cross_equity": "15.0",
	//            "cross_unrealized_pnl": "0.0"
	//        }
	//    }
	//
	var result any = this.SafeDict(response, "result", map[string]any{})

	ch <- this.ParseBalance(result)
	return nil
}
func (this *GrvtCore) ParseBalance(response any) any {
	//
	//        {
	//            "event_time": "1764863116142428457",
	//            "sub_account_id": "2147050003876484",
	//            "margin_type": "SIMPLE_CROSS_MARGIN",
	//            "settle_currency": "USDT",
	//            "unrealized_pnl": "0.0",
	//            "total_equity": "15.0",
	//            "initial_margin": "0.0",
	//            "maintenance_margin": "0.0",
	//            "available_balance": "15.0",
	//            "spot_balances": [
	//                {
	//                    "currency": "USDT",
	//                    "balance": "15.0",
	//                    "index_price": "1.000289735"
	//                }
	//            ],
	//            "positions": [],
	//            "settle_index_price": "1.000289735",
	//            "derisk_margin": "0.0",
	//            "derisk_to_maintenance_margin_ratio": "1.0",
	//            "total_cross_equity": "15.0",
	//            "cross_unrealized_pnl": "0.0"
	//        }
	//
	var timestamp *int64 = this.SafeIntegerProduct(response, "event_time", 0.000001)
	var result map[string]any = map[string]any{
		"info":      response,
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
	var spotBalances any = this.SafeList(response, "spot_balances", []any{})
	var availableBalance *string = this.SafeString(response, "available_balance")
	for i := 0; IsLessThan(i, GetArrayLength(spotBalances)); i++ {
		var balance any = GetValue(spotBalances, i)
		var currencyId *string = this.SafeString(balance, "currency")
		var code any = this.SafeCurrencyCode(currencyId)
		var account any = this.Account()
		AddElementToObject(account, "total", this.SafeString(balance, "balance"))
		AddElementToObject(account, "free", availableBalance) // todo: revise after API team clarification
		if !IsEqual(code, nil) {
			AddElementToObject(result, code, account)
		}
	}
	return this.SafeBalance(result)
}

/**
 * @method
 * @name grvt#fetchDeposits
 * @description fetch all deposits made to an account
 * @see https://api-docs.grvt.io/trading_api/#transfer
 * @param {string} [code] unified currency code
 * @param {int} [since] the earliest time in ms to fetch deposits for
 * @param {int} [limit] the maximum number of deposits structures to retrieve
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {int} [params.until] timestamp in ms of the latest item
 * @returns {object[]} a list of [transaction structures]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
